from collections import deque
def transform(grid):
    h,w=len(grid),len(grid[0])
    seen=set()
    for r in range(h):
        for c in range(w):
            if grid[r][c]!=6 and (r,c) not in seen:
                q=deque([(r,c)]); seen.add((r,c)); comp=[]; edge=False
                while q:
                    a,b=q.popleft(); comp.append((a,b))
                    if a==0 or b==0 or a==h-1 or b==w-1: edge=True
                    for x,y in ((a-1,b),(a+1,b),(a,b-1),(a,b+1)):
                        if 0<=x<h and 0<=y<w and grid[x][y]!=6 and (x,y) not in seen:
                            seen.add((x,y)); q.append((x,y))
                if not edge:
                    for a,b in comp: grid[a][b]=4
    return grid
